// Combine note + candidate + job data, normalize phone, pick template
const note = $('On Note Stage Change').first().json;
const candidate = $('Fetch Candidate').first().json;
const job = $('Fetch Job').first().json;

if (!candidate.phone) {
  return { skip: true, reason: 'no_candidate_phone' };
}

let s = String(candidate.phone).replace(/[\s\-\(\)]/g, '');
let e164;
if (s.startsWith('+')) e164 = s;
else if (s.startsWith('0')) e164 = '+6' + s;
else if (s.startsWith('60') || s.startsWith('65')) e164 = '+' + s;
else e164 = '+' + s;

if (!/^\+\d{8,15}$/.test(e164)) return { skip: true, reason: 'invalid_phone' };

const firstName = (candidate.firstName || candidate.name || 'there').split(' ')[0];
const language = candidate.locale === 'zh' ? 'zh_CN' : 'en';

// Template selection by stage
let templateName, variables;
switch (note.stage) {
  case 'Interviewing':
    templateName = 'candidate_interview_invite';
    // Note: requires note to have interviewDate, interviewTime, interviewFormat
    variables = [
      firstName,
      job.title || 'the role',
      note.interviewDate || 'TBC',
      note.interviewTime || 'TBC',
      note.interviewFormat || 'In-person'
    ];
    break;
  case 'Offer Out':
    templateName = 'candidate_offer_notification';
    variables = [firstName, job.title || 'the role'];
    break;
  case 'Filled':
    templateName = 'candidate_placement_confirmed';
    variables = [firstName, job.title || 'the role'];
    break;
  default:
    return { skip: true, reason: `stage_no_template:${note.stage}` };
}

return {
  phoneE164: e164,
  templateName,
  language,
  variables,
  candidateId: candidate.id || note.candidateId,
  jobId: job.id || note.jobId
};
